storyBeats.text:
-- Foundation or Practitioner difficulty:
SELECT title FROM quests
WHERE difficulty IN ('Foundation', 'Practitioner');

-- Mid-tier rewards (200-500 xp, inclusive):
SELECT title, xp_reward FROM quests
WHERE xp_reward BETWEEN 200 AND 500;

-- Quests with 'the' in the title:
SELECT title FROM quests
WHERE title LIKE '%the%';

-- Quests nobody has completed yet:
SELECT title FROM quests
WHERE completed_by IS NULL;
